import { mkdirSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ControlCommand } from "../../control.ts";
import { assemblePdf, SETTINGS_FILE, tmpPath } from "../../util.ts";
import { launchControlled, killAndWait, sendCommandSync } from "../../win-automation.ts";
import { findTopWindow, postMessage, sleep, WM_CLOSE } from "../../winapi.ts";

const results: object[] = [];
function formPdf(): string {
  return assemblePdf([
    "<< /Type /Catalog /Pages 2 0 R /AcroForm << /Fields [4 0 R] /DR << /Font << /Helv 5 0 R >> >> >> >>",
    "<< /Type /Pages /Count 1 /Kids [3 0 R] >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 700] /Annots [4 0 R] >>",
    "<< /Type /Annot /Subtype /Widget /FT /Tx /T (name) /V (OLDWORD) /Rect [100 300 500 400] /P 3 0 R /F 4 /DA (/Helv 18 Tf 0 g) >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ]);
}

for (const engine of ["pdfium", "mupdf"]) {
  for (const action of ["keep", "rename"]) {
    const dir = tmpPath(`full-review/${engine}-${action}`);
    mkdirSync(dir, { recursive: true });
    const source = join(dir, "source.pdf");
    writeFileSync(source, formPdf(), "latin1");
    writeFileSync(join(dir, SETTINGS_FILE), "UiLanguage = en\nReloadModifiedDocuments = false\nRestoreSession = false\n");
    const { proc, client, frame } = await launchControlled(["-appdata", dir, "-log-to-file", join(dir, "app.log"), source], {
      env: { ...process.env, SOLOKPDF_ENGINE: engine },
    });
    try {
      await client.waitForRenderIdle();
      const before = await client.request(ControlCommand.TestCurrentPdf, ["cached-text", 1]);
      const set = await client.setFormField(1, 0, "NEWWORD");
      if (set[0] !== 0 || !String(set[1]).includes("after='NEWWORD'")) throw new Error(`edit failed: ${set}`);
      const after = await client.request(ControlCommand.TestCurrentPdf, ["cached-text", 1]);
      const search = await client.request(ControlCommand.TestCurrentPdf, ["NEWWORD"]);
      const dirty = await client.request(ControlCommand.TestMarkupAnnots, []);
      if (!String(dirty[1]).includes("modified=1")) throw new Error(`not dirty: ${dirty}`);
      if (action === "rename") renameSync(source, join(dir, "moved.pdf"));
      postMessage(frame, WM_CLOSE, 0, 0);
      const deadline = Date.now() + 5000;
      let dialog = 0;
      while (Date.now() < deadline && proc.exitCode === null && !(dialog = findTopWindow(proc.pid!, "#32770"))) await sleep(25);
      const row = { engine, action, before, set, after, search, dirty: String(dirty[1]).match(/undo[^\n]*/), dialog: !!dialog, exit: proc.exitCode };
      results.push(row);
      console.log(JSON.stringify(row));
      if (dialog) {
        postMessage(dialog, WM_CLOSE, 0, 0);
        await sleep(100);
      }
    } finally {
      client.close();
      if (proc.exitCode === null) await killAndWait(proc);
    }
  }
}
writeFileSync(tmpPath("full-review/probe-results.json"), JSON.stringify(results, null, 2));

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ControlCommand } from "../../control.ts";
import { assemblePdf, SETTINGS_FILE, tmpPath } from "../../util.ts";
import { launchControlled, killAndWait } from "../../win-automation.ts";
import { findTopWindow, sleep } from "../../winapi.ts";

function fixture(word: string): string {
  return assemblePdf([
    "<< /Type /Catalog /Pages 2 0 R /AcroForm << /Fields [4 0 R] /DR << /Font << /Helv 5 0 R >> >> >> >>",
    "<< /Type /Pages /Count 1 /Kids [3 0 R] >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 700] /Annots [4 0 R] >>",
    `<< /Type /Annot /Subtype /Widget /FT /Tx /T (name) /V (${word}) /Rect [100 300 500 400] /P 3 0 R /F 4 /DA (/Helv 18 Tf 0 g) >>`,
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
  ]);
}

const results: object[] = [];
for (const engine of ["pdfium", "mupdf"]) {
  for (let repeat = 0; repeat < 2; repeat++) {
    const dir = tmpPath(`full-review/reload-${engine}-${repeat}`);
    mkdirSync(dir, { recursive: true });
    const path = join(dir, "source.pdf");
    writeFileSync(path, fixture("OLDWORD"), "latin1");
    writeFileSync(join(dir, SETTINGS_FILE), "UiLanguage = en\nReloadModifiedDocuments = true\nRestoreSession = false\n");
    const { proc, client } = await launchControlled(["-appdata", dir, "-log-to-file", join(dir, "app.log"), path], {
      env: { ...process.env, SOLOKPDF_ENGINE: engine },
    });
    try {
      await client.waitForRenderIdle();
      const set = await client.setFormField(1, 0, "NEWWORD");
      if (set[0] !== 0) throw new Error(String(set));
      const before = String((await client.request(ControlCommand.TestMarkupAnnots, []))[1]);
      if (!before.includes("modified=1")) throw new Error("not dirty");
      writeFileSync(path, fixture("DISKWORD"), "latin1");
      const deadline = Date.now() + 8000;
      let dialog = 0;
      let after = "";
      while (Date.now() < deadline) {
        dialog = findTopWindow(proc.pid!, "#32770");
        if (dialog) break;
        after = String((await client.request(ControlCommand.TestMarkupAnnots, []))[1]);
        if (after.includes("modified=0")) break;
        await sleep(50);
      }
      const text = dialog ? [] : await client.request(ControlCommand.TestCurrentPdf, ["cached-text", 1]);
      const row = { engine, repeat, set, before: before.match(/undo[^\n]*/)?.[0], after: after.match(/undo[^\n]*/)?.[0], dialog: !!dialog, text };
      results.push(row);
      console.log(JSON.stringify(row));
    } finally {
      client.close();
      await killAndWait(proc);
    }
  }
}
writeFileSync(tmpPath("full-review/reload-results.json"), JSON.stringify(results, null, 2));

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ControlCommand } from "../../control.ts";
import { writeTestPfx } from "../../pki.ts";
import { assemblePdf, cmdId, SETTINGS_FILE, tmpPath } from "../../util.ts";
import { launchControlled, killAndWait, sendCommand, pressEnter, moveTestCursor, findCanvas } from "../../win-automation.ts";
import { enumWindows, enumChildWindows, getClassName, getWindowPid, getWindowText, getClientRect, clientToScreen, sendMessage, sendText, postMessage, packCoords, sleep, WM_CLOSE } from "../../winapi.ts";

function top(pid: number, cls: string, title?: string): number {
  let found = 0;
  enumWindows((h) => {
    if (getWindowPid(h) === pid && getClassName(h) === cls && (title === undefined || getWindowText(h) === title)) found = h;
    return true;
  });
  return found;
}
function children(hwnd: number, cls: string): number[] {
  const out: number[] = [];
  enumChildWindows(hwnd, (h) => { if (getClassName(h) === cls) out.push(h); return true; });
  return out;
}
async function waitFor(f: () => number): Promise<number> {
  for (const until = Date.now() + 5000; Date.now() < until;) { const h = f(); if (h) return h; await sleep(25); }
  throw new Error("window timeout");
}
const rows: object[] = [];
for (const engine of ["pdfium", "mupdf"]) {
  const dir = tmpPath(`full-review/sign-failure-${engine}`);
  mkdirSync(dir, { recursive: true });
  const pdf = join(dir, "source.pdf"), pfx = join(dir, "cert.pfx"), img = join(dir, "broken.png");
  writeTestPfx(pfx, "ReviewTest", "pw");
  writeFileSync(img, "not an image");
  writeFileSync(pdf, assemblePdf(["<< /Type /Catalog /Pages 2 0 R >>", "<< /Type /Pages /Count 1 /Kids [3 0 R] >>", "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 700] >>"]), "latin1");
  writeFileSync(join(dir, SETTINGS_FILE), "UiLanguage = en\nRestoreSession = false\n");
  const { proc, client, frame } = await launchControlled(["-appdata", dir, "-log-to-file", join(dir, "app.log"), pdf], {env: {...process.env, SOLOKPDF_ENGINE: engine}});
  try {
    await client.waitForRenderIdle();
    sendCommand(frame, cmdId("CmdSignDocument"));
    const dlg = await waitFor(() => top(proc.pid!, "SumatraWgDefaultWinClass", "Sign Document"));
    await waitFor(() => children(dlg, "Edit").length === 5 ? 1 : 0);
    const edits = children(dlg, "Edit"), combos = children(dlg, "ComboBox");
    if (edits.length !== 5) throw new Error(`edits=${edits.length}`);
    const fieldsBefore = Number(sendMessage(combos[1], 0x0146, 0, 0));
    sendMessage(combos[0], 0x014e, Number(sendMessage(combos[0], 0x0146, 0, 0)) - 1, 0);
    sendText(edits[0], pfx); sendText(edits[1], "pw"); sendText(edits[4], img);
    await pressEnter(dlg);
    await sleep(100);
    const canvas = findCanvas(frame), rect = getClientRect(canvas);
    const x = Math.floor(rect.right / 2), y = Math.floor(rect.bottom / 2);
    const screen = clientToScreen(canvas, x, y);
    await moveTestCursor(screen.x, screen.y, client);
    postMessage(canvas, 0x0201, 1, packCoords(x, y));
    postMessage(canvas, 0x0202, 0, packCoords(x, y));
    const error = await waitFor(() => top(proc.pid!, "#32770"));
    const errorTitle = getWindowText(error);
    postMessage(error, WM_CLOSE, 0, 0);
    await sleep(100);
    postMessage(dlg, WM_CLOSE, 0, 0);
    await sleep(100);
    const state = String((await client.request(ControlCommand.TestMarkupAnnots, []))[1]);
    sendCommand(frame, cmdId("CmdSignDocument"));
    const reopened = await waitFor(() => top(proc.pid!, "SumatraWgDefaultWinClass", "Sign Document"));
    await waitFor(() => children(reopened, "ComboBox").length >= 3 ? 1 : 0);
    const fieldsAfter = Number(sendMessage(children(reopened, "ComboBox")[1], 0x0146, 0, 0));
    postMessage(reopened, WM_CLOSE, 0, 0);
    const row = { engine, errorTitle, fieldsBefore, fieldsAfter, state: state.match(/undo[^\n]*/)?.[0] };
    rows.push(row); console.log(JSON.stringify(row));
  } finally { client.close(); await killAndWait(proc); }
}
writeFileSync(tmpPath("full-review/sign-failure-results.json"), JSON.stringify(rows, null, 2));
